function normalize(t){let d=defaultTool(),n=Object.assign(d,t||{});n.schedule=Object.assign(defaultTool().schedule,t?.schedule||{});n.admin=Object.assign(makeAdmin(0),t?.admin||{});n.ncs=t?.ncs||[];if(!n.codename){if(n.family==='Regera'||n.model?.startsWith('R9'))n.codename='Regera';else if(n.family==='Celestiq'||n.model?.startsWith('D11'))n.codename='Celestiq';else n.codename='Panamera'}n.family='29XX';if(n.quarterStatus==='Active in FI')n.quarterStatus='In FI';if(n.quarterStatus==='Waiting for FI handoff'||n.quarterStatus==='Planned')n.quarterStatus='Waiting for FI';return n}
function loadState(){
 for(const k of [KEY,...OLD_STATE_KEYS]){try{let s=JSON.parse(localStorage.getItem(k)||'null');if(s&&s.tools){s.config=normalizeConfig(s.config);s.tools=(s.tools||[]).map(normalize).map(t=>syncToolConfig(t,s.config));s.weekday=s.weekday||{title:'B7 WEEKDAY PRIORITIES',notes:''};s.weekend=s.weekend||{title:'B7 WEEKEND PRIORITIES',volunteers:[]};return s}}catch(e){}}
 for(const k of OLD_TOOL_KEYS){try{let a=JSON.parse(localStorage.getItem(k)||'null');if(Array.isArray(a)){let c=defaultConfig();return {tools:a.map(normalize).map(t=>syncToolConfig(t,c)),weekday:{title:'B7 WEEKDAY PRIORITIES',notes:''},weekend:{title:'B7 WEEKEND PRIORITIES',volunteers:[]},config:c}}}catch(e){}}
 let c=defaultConfig();return {tools:SAMPLE.map(normalize).map(t=>syncToolConfig(t,c)),weekday:{title:'B7 WEEKDAY PRIORITIES',notes:''},weekend:{title:'B7 WEEKEND PRIORITIES',volunteers:[{name:'Vinh',sat:'6am to 12pm',sun:'',notes:''},{name:'Quoc',sat:'6am to 4pm',sun:'',notes:''},{name:'Singapore team',sat:'6am to XXXX',sun:'6am to XXXX',notes:'Coverage based on volunteer list'}]},config:c}
}
let state=loadState(),tools=state.tools,view='countdown',selectedId=null;
function save(){state.tools=tools;state.config=normalizeConfig(state.config);localStorage.setItem(KEY,JSON.stringify(state))}
function current(){return tools}
function quarterLabel(){let c={};tools.forEach(t=>c[t.quarter]=(c[t.quarter]||0)+1);return Object.entries(c).sort((a,b)=>b[1]-a[1])[0]?.[0]||'Quarter Not Set'}
function pct(a,b){return b?Math.round(a/b*100):0}
function qState(t){return t.quarterStatus==='Shipped'?'shipped':t.quarterStatus==='Waiting for FI'?'waiting':'infi'}
function tone(t){if(t.quarterStatus==='Shipped')return'good';if(t.fiStatus==='Line Down'||t.ncs.some(n=>n.blocking))return'bad';if(t.fiStatus==='Performing POA'||/trouble|waiting/i.test(t.activity))return'warn';return'good'}
function adminProgress(t){let tasks=activeLeadTasks().filter(x=>x.countProgress!==false),vals=tasks.map(x=>t.leadAdmin?.[x.id]??'Not Started').filter(x=>x!=='N/A'),done=vals.filter(x=>x==='Complete').length;return pct(done,vals.length)}
function routeIndex(t){return Math.max(0,routeFor(t).findIndex(x=>x[0]===t.checklist))}
function routeCounts(t){let r=routeFor(t),i=routeIndex(t),done=t.quarterStatus==='Shipped'?r.length:Math.max(0,i);return {done,total:r.length,current:Math.min(i+1,r.length)}}
function leadCounts(t){let tasks=activeLeadTasks().filter(x=>x.countProgress!==false),applicable=tasks.filter(x=>(t.leadAdmin?.[x.id]??'Not Started')!=='N/A'),done=applicable.filter(x=>(t.leadAdmin?.[x.id]??'Not Started')==='Complete').length;return {done,total:applicable.length}}
function routeWorkflow(t){let r=routeFor(t),idx=routeIndex(t),shipped=t.quarterStatus==='Shipped';return `<div class="workflow-list">${r.map((x,i)=>{let done=shipped||i<idx,current=!shipped&&i===idx;return `<div class="workflow-step ${done?'done':current?'current':''}"><span class="step-icon">${done?'✓':current?'●':'○'}</span><span class="step-name"><b>${esc(x[0])}</b><span class="step-sub">${esc(x[1])}</span></span><span class="step-state">${done?'Complete':current?'Current':'Upcoming'}</span></div>`}).join('')}</div>`}
function leadWorkflow(t,editable=false){let tasks=activeLeadTasks();return `<div class="workflow-list">${tasks.map((task,i)=>{let val=t.leadAdmin?.[task.id]??'Not Started',done=val==='Complete',na=val==='N/A';return `<div class="workflow-step ${done?'done':na?'na':val==='In Progress'?'current':''}"><span class="step-icon">${done?'✓':na?'—':val==='In Progress'?'●':'○'}</span><span class="step-name"><span class="order-pill">${i+1}</span> ${esc(task.label)}</span><span class="step-state">${editable?leadStateControl(task,val):esc(val)}</span></div>`}).join('')}</div>`}
function leadStateControl(task,val){let opts=(task.options?.length?task.options:DEFAULT_TASK_CHOICES);return `<select class="task-state" data-task-id="${esc(task.id)}">${opts.map(o=>`<option ${o===val?'selected':''}>${esc(o)}</option>`).join('')}</select>`}
function customFieldValueControl(field,t){let v=t.custom?.[field.id]??'',id='cf_'+field.id;if(field.type==='Dropdown'){if(field.allowCustom){return `<input id="${id}" data-custom-id="${esc(field.id)}" list="list_${esc(field.id)}" value="${esc(v)}"><datalist id="list_${esc(field.id)}">${(field.options||[]).map(o=>`<option value="${esc(o)}"></option>`).join('')}</datalist>`}return `<select id="${id}" data-custom-id="${esc(field.id)}"><option value=""></option>${(field.options||[]).map(o=>`<option ${o===v?'selected':''}>${esc(o)}</option>`).join('')}</select>`}let typ=field.type==='Number'?'number':field.type==='Date'?'date':'text';return `<input id="${id}" type="${typ}" data-custom-id="${esc(field.id)}" value="${esc(v)}">`}
function customStatusBlock(t){let fs=(state.config.customFields||[]).filter(f=>f.active!==false&&f.showStatus!==false);if(!fs.length)return'';return `<div class="tool-status-block"><h3>Additional Fields</h3><div class="tool-status-extra">${fs.map(f=>kv(f.label,t.custom?.[f.id]||'—')).join('')}</div></div>`}
function page(title,desc,k='B7 FI OPERATIONS'){return `<div class="page-title"><div><div class="page-kicker">${k}</div><h2>${title}</h2><p>${desc}</p></div></div>`}
function reportHeader(title,sub=''){return `<div class="report-title"><h2>${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div>`}
function actions(items,shot=true){let a=[...items];if(shot)a.push({label:'Screenshot Mode',fn:enterScreenshot});floating.innerHTML=a.map((x,i)=>`<button class="btn ${x.primary?'primary':''}" data-act="${i}">${x.label}</button>`).join('');a.forEach((x,i)=>floating.querySelector(`[data-act="${i}"]`).onclick=x.fn)}
function enterScreenshot(){document.body.classList.add('screenshot-mode');let b=$('#screenshotExit');b.style.display='block';setTimeout(()=>{if(document.body.classList.contains('screenshot-mode'))b.style.display='none'},1800)}function exitScreenshot(){document.body.classList.remove('screenshot-mode');$('#screenshotExit').style.display=''}$('#screenshotExit').onclick=exitScreenshot;document.addEventListener('keydown',e=>{if(e.key==='Escape')exitScreenshot()});
function setView(v){view=v;document.body.dataset.theme=v==='systems'?'systems':v;document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===v));render();scrollTo({top:190,behavior:'smooth'})}document.querySelectorAll('.nav-btn').forEach(b=>b.onclick=()=>setView(b.dataset.view));
function typeGroups(){let g={};tools.forEach(t=>(g[t.codename]??=[]).push(t));return Object.entries(g).sort((a,b)=>a[0].localeCompare(b[0]))}
function countdown(){let total=tools.length,sh=tools.filter(t=>t.quarterStatus==='Shipped').length,need=total-sh;app.innerHTML=page('Quarter Tool Shipping Countdown','Digital version of the wall countdown, with the remaining workload broken down by product code name.','QUARTER PLAN')+`<div class="report-screen">${reportHeader(`${quarterLabel()} TOOL SHIPPING COUNTDOWN`)}<div class="overall-countdown"><div class="overall-box"><div class="label">Total Tools</div><span class="number">${total}</span></div><div class="overall-box need"><div class="label">Need to Ship</div><span class="number">${need}</span></div><div class="overall-box shipped"><div class="label">Shipped</div><span class="number">${sh}</span></div></div><div class="quarter-progress"><div class="progress-label"><span>Quarter Shipping Progress</span><b>${pct(sh,total)}% Shipped</b></div><div class="track"><div class="fill" style="width:${pct(sh,total)}%;background:var(--good)"></div></div></div>${typeGroups().map(([name,a])=>{let ss=a.filter(t=>t.quarterStatus==='Shipped').length,w=a.filter(t=>t.quarterStatus==='Waiting for FI').length,i=a.filter(t=>t.quarterStatus==='In FI').length;return `<section class="type-section"><div class="type-header"><div><div class="page-kicker">PRODUCT CODE NAME</div><h3>${esc(name)}</h3></div><div class="type-summary"><div class="type-count"><small>Total</small><b>${a.length}</b></div><div class="type-count need"><small>Need to Ship</small><b>${a.length-ss}</b></div><div class="type-count waiting"><small>Waiting FI</small><b>${w}</b></div><div class="type-count infi"><small>In FI</small><b>${i}</b></div><div class="type-count shipped"><small>Shipped</small><b>${ss}</b></div></div></div><div class="countdown-card-grid">${a.sort((x,y)=>(x.ship||'9').localeCompare(y.ship||'9')).map(t=>`<div class="countdown-card ${qState(t)}"><div class="cc-head"><div><div class="cc-id">${esc(t.id)}</div><b>${esc(t.model)}</b><div class="gray">${esc(t.customer)}</div></div>${t.quarterStatus==='Shipped'?'<span class="complete-mark"><span class="check">✓</span> SHIPPED</span>':`<span class="state-chip ${qState(t)}">${t.quarterStatus==='Waiting for FI'?'WAITING FI':'IN FI'}</span>`}</div><div class="cc-meta"><div><span>MFG Ship Date</span><b>${fmt(t.ship)}</b></div><div><span>Sales Order</span><b>${esc(t.so)}</b></div></div></div>`).join('')}</div></section>`}).join('')}</div>`;actions([{label:'Edit Tool Countdown',primary:true,fn:()=>admin('countdown')},{label:'Administration',fn:()=>setView('admin')}])}
function shipping(){let a=tools.filter(t=>t.schedule.publish!=='Draft'||t.schedule.subsystems||t.schedule.is||t.quarterStatus==='Shipped');app.innerHTML=page('Shipping Schedule','Screenshot-ready shipping plans generated from Shipping Schedule Admin.','SHIPPING COORDINATION')+`<div class="report-screen">${reportHeader('B7 FI SHIPPING SCHEDULES')}${a.map(t=>`<div class="shipping-plan ${t.schedule.publish==='Complete'||t.quarterStatus==='Shipped'?'complete':''}"><div class="shipping-plan-head"><h3>SHIPPING PLAN FOR ${esc(t.codename.toUpperCase())} ${esc(t.id)}</h3>${t.schedule.publish==='Complete'||t.quarterStatus==='Shipped'?'<span class="complete-mark"><span class="check">✓</span> COMPLETE</span>':`<span class="badge info">${esc(t.schedule.publish)} · ${esc(t.schedule.status)}</span>`}</div><div style="overflow:auto"><table class="shipping-table"><thead><tr><th>System</th><th>Subsystems - Handoff</th><th>Cable Kit - Handoff</th><th>Accessories - Handoff</th><th>MST Install</th><th>IS - Handoff</th><th>Notes</th></tr></thead><tbody><tr><td>${esc(t.id)}</td><td>${fmtShort(t.schedule.subsystems)}</td><td>${fmtShort(t.schedule.cables)}</td><td>${fmtShort(t.schedule.accessories)}</td><td>${fmtShort(t.schedule.mst)}</td><td>${fmtShort(t.schedule.is)}</td><td>${esc(t.schedule.notes)}</td></tr></tbody></table></div></div>`).join('')||'<div class="notice">No shipping schedules have been published yet.</div>'}</div>`;actions([{label:'Edit Shipping Schedules',primary:true,fn:()=>admin('shipping')},{label:'Administration',fn:()=>setView('admin')}])}
function priorityRows(type){let key=type==='weekend'?'weekendPriority':'dailyPriority',assignment=type==='weekend'?'weekendAssignment':'weekdayAssignment';return tools.filter(t=>t[key]).sort((a,b)=>a[key]-b[key]).map(t=>`<tr><td><span class="priority-num">${t[key]}</span></td><td><b>${esc(t.id)}</b></td><td>${esc(t.model)}</td><td>${esc(t.so)}</td><td>${esc(t.customer)}</td><td>${fmt(t.ship)}</td><td>${esc(t.room)}</td><td>${esc(t[assignment]||t.driver)}</td><td class="notes-cell">${esc(type==='weekend'?t.weekendNotes:t.priorityNotes||t.activity)}</td></tr>`).join('')}
function priorityTable(type){return `<div class="table-wrap"><table class="report-table priority-table"><thead><tr><th>Priority</th><th>${esc(lbl('utid','UTID'))}</th><th>Model</th><th>${esc(lbl('salesOrder','Sales Order'))}</th><th>${esc(lbl('customer','Customer'))}</th><th>${esc(lbl('shipDate','Ship Date'))}</th><th>${esc(lbl('cleanroom','Cleanroom'))}</th><th>${esc(lbl('assignment','Tool Assignments'))}</th><th>Notes</th></tr></thead><tbody>${priorityRows(type)}</tbody></table></div>`}
function daily(){app.innerHTML=page('Weekday Priorities','Automatically generated from the current tool records and weekday priority order.','WEEKDAY OPERATIONS')+`<div class="report-screen">${reportHeader(state.weekday.title||'B7 WEEKDAY PRIORITIES')}${priorityTable('daily')}</div>`;actions([{label:'Edit Weekday Priorities',primary:true,fn:()=>admin('daily')},{label:'Administration',fn:()=>setView('admin')}])}
function volunteerTable(){let v=state.weekend.volunteers||[];return `<div class="table-wrap"><table class="report-table volunteer-table"><thead><tr><th>Weekend Volunteers</th><th>Saturday Hours</th><th>Sunday Hours</th><th>Notes</th></tr></thead><tbody>${v.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.sat)}</td><td>${esc(x.sun)}</td><td>${esc(x.notes)}</td></tr>`).join('')||'<tr><td colspan="4">No volunteer schedule entered.</td></tr>'}</tbody></table></div>`}
function weekend(){app.innerHTML=page('Weekend Priorities','Weekend volunteer coverage first, then the priority plan built around the available crew.','WEEKEND OPERATIONS')+`<div class="report-screen">${reportHeader(state.weekend.title||'B7 WEEKEND PRIORITIES')}${volunteerTable()}<div style="height:16px"></div>${priorityTable('weekend')}</div>`;actions([{label:'Edit Weekend Plan',primary:true,fn:()=>admin('weekend')},{label:'Administration',fn:()=>setView('admin')}])}
function morning(){let a=tools.filter(t=>t.quarterStatus!=='Shipped').sort((x,y)=>(x.dailyPriority??999)-(y.dailyPriority??999));app.innerHTML=page('Morning Status','Generated from the latest Tool records for the manager morning meeting.','MANAGER STATUS')+`<div class="report-screen">${reportHeader('B7 FI MORNING STATUS')}${a.map(t=>{let escal=t.ncs.filter(n=>n.state==='Escalated').map(n=>`${n.id} – Day ${n.days||0}`).join(', ');return `<div class="meeting-row"><div class="meeting-main">${esc(t.id)} (${esc(t.room)}) (${esc(t.model)} - ${esc(t.codename)}) (SW: ${esc(t.sw||'—')}) ${esc(t.checklist)}: ${esc(checkName(t))} (${esc(t.customer)}, ${fmt(t.ship)}) (Lamp Hours: ${t.lamp||0}) ${t.process==='Reduced Process'?'Reduced Process':''} ${escal?`(Escalated ${esc(escal)})`:''}</div><ul class="meeting-bullets"><li>${esc(t.activity||'No latest status entered.')}</li>${t.ncs.filter(n=>n.state!=='Escalated').map(n=>`<li>${esc(n.id)}: ${esc(n.desc)}</li>`).join('')}</ul></div>`}).join('')}</div>`;actions([{label:'Morning Quick Update',primary:true,fn:()=>admin('meeting')},{label:'Administration',fn:()=>setView('admin')}])}
function systems(){app.innerHTML=page('Tools','Every current system as a live card. Click a card for the complete ordered FI + Lead/Admin workflow.','SYSTEM STATUS')+`<div class="system-grid">${tools.map(t=>{let rc=routeCounts(t),lc=leadCounts(t);return `<div class="system-card ${t.quarterStatus==='Shipped'?'shipped-card':t.quarterStatus==='Waiting for FI'?'waiting-card':'infi-card'}" data-tool="${esc(t.id)}"><div class="system-head"><div><div class="tool-family"><span class="tool-glyph"></span>${esc(t.codename)}</div><div class="system-id">${esc(t.id)}</div><div class="gray">${esc(t.model)} · ${esc(t.customer)}</div></div>${t.quarterStatus==='Shipped'?'<span class="complete-mark"><span class="check">✓</span> SHIPPED</span>':`<span><span class="status-dot ${tone(t)}"></span>${esc(t.fiStatus)}</span>`}</div><div class="progress-row"><div class="progress-label"><span>TOOL PROGRESS</span><b>${t.quarterStatus==='Shipped'?100:routeProgress(t)}%</b></div><div class="track"><div class="fill" style="width:${t.quarterStatus==='Shipped'?100:routeProgress(t)}%"></div></div><div class="card-progress-meta"><span>${rc.done} completed</span><span>${rc.current}/${rc.total} current step</span></div></div><div class="progress-row"><div class="progress-label"><span>LEAD / ADMIN</span><b>${t.quarterStatus==='Shipped'?100:adminProgress(t)}%</b></div><div class="track"><div class="fill admin" style="width:${t.quarterStatus==='Shipped'?100:adminProgress(t)}%"></div></div><div class="card-progress-meta"><span>${lc.done} complete</span><span>${lc.total} applicable tasks</span></div></div><div class="card-meta"><div><span>Driver</span><strong>${esc(t.driver)}</strong></div><div><span>Location</span><strong>${esc(t.room)}</strong></div><div><span>Checklist</span><strong>${esc(t.checklist)}</strong></div><div><span>MFG Ship</span><strong>${fmt(t.ship)}</strong></div></div></div>`}).join('')}</div>`;document.querySelectorAll('[data-tool]').forEach(x=>x.onclick=()=>toolStatus(x.dataset.tool));actions([{label:'Add Tool',primary:true,fn:()=>toolAdmin()},{label:'Administration',fn:()=>setView('admin')}],false)}
function kv(k,v){return `<div class="kv"><span>${k}</span><b>${v||'—'}</b></div>`}
function toolStatus(id){let t=tools.find(x=>x.id===id);if(!t)return;selectedId=id;document.body.dataset.theme='systems';let rc=routeCounts(t),lc=leadCounts(t);app.innerHTML=page(`${esc(t.id)} · ${esc(t.model)}`,`${esc(t.codename)} · ${esc(t.customer)} · ${esc(t.room)}`,'INDIVIDUAL TOOL STATUS')+`<div class="report-screen">${reportHeader(`${t.id} TOOL STATUS`,`${t.model} · ${t.codename} · ${t.customer}`)}<div class="metric-grid"><div class="metric"><span>${esc(lbl('shipDate','MFG Ship Date'))}</span><strong style="font-size:20px">${fmt(t.ship)}</strong></div><div class="metric"><span>${esc(lbl('currentChecklist','Current Checklist'))}</span><strong style="font-size:18px">${esc(t.checklist)}</strong><small>${esc(checkName(t))}</small></div><div class="metric"><span>Tool Progress</span><strong>${routeProgress(t)}%</strong><small>${rc.done}/${rc.total} completed</small></div><div class="metric"><span>Lead / Admin</span><strong>${adminProgress(t)}%</strong><small>${lc.done}/${lc.total} applicable</small></div><div class="metric"><span>FI Status</span><strong style="font-size:18px">${esc(t.fiStatus)}</strong></div></div><div class="tool-status-grid"><div class="tool-status-block"><h3>Tool Information</h3>${kv('Product Family',t.family)}${kv('Code Name',t.codename)}${kv('Model',t.model)}${kv(lbl('utid','UTID'),t.id)}${kv(lbl('salesOrder','Sales Order'),t.so)}${kv(lbl('customer','Customer'),t.customer)}${kv(lbl('cleanroom','Cleanroom'),t.room)}${kv(lbl('assignment','Tool Assignment'),t.driver)}${kv(lbl('swVersion','SW Version'),t.sw)}${kv(lbl('fiProcess','FI Process'),t.process)}${kv(lbl('lampHours','Lamp Hours'),String(t.lamp||0))}</div><div class="tool-status-block"><h3>FI Status / Issues</h3>${kv(lbl('currentChecklist','Current Checklist'),`${t.checklist} — ${checkName(t)}`)}${kv(lbl('latestStatus','Latest Status'),t.activity)}${kv('POA',t.poa)}${kv('Escalation Meeting',t.escalationMeeting)}${kv('Waivers',t.waivers)}${kv('Open NCs',t.ncs.map(n=>n.id+' '+n.state).join(', ')||'None')}</div><div class="tool-status-block"><h3>Shipping Schedule</h3>${kv('Schedule',t.schedule.publish+' / '+t.schedule.status)}${kv('Subsystems',fmt(t.schedule.subsystems))}${kv('Cable Kit',fmt(t.schedule.cables))}${kv('Accessories',fmt(t.schedule.accessories))}${kv('MST',fmt(t.schedule.mst))}${kv('IS',fmt(t.schedule.is))}${kv('Notes',t.schedule.notes)}</div>${customStatusBlock(t)}</div><div class="progress-board"><div class="progress-panel"><h3>FI Checklist Route · ${rc.done}/${rc.total} Complete</h3>${routeWorkflow(t)}</div><div class="progress-panel"><h3>Lead / Admin Workflow · ${lc.done}/${lc.total} Complete</h3>${leadWorkflow(t,false)}</div></div></div>`;actions([{label:'Edit This Tool',primary:true,fn:()=>toolAdmin(t.id)},{label:'Back to Tools',fn:()=>setView('systems')}])}
function admin(section='home'){view='admin';document.body.dataset.theme='admin';document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view==='admin'));let tabs=[['home','Admin Home'],['tools','Tool Admin'],['countdown','Countdown'],['shipping','Shipping'],['daily','Weekday'],['meeting','Morning'],['weekend','Weekend'],['config','Configuration']];app.innerHTML=page('Administration','Edit the shared master data behind every clean status/report page.','CONTROL & EDITING')+`<div class="admin-tabs">${tabs.map(x=>`<button class="admin-tab ${section===x[0]?'active':''}" data-admin="${x[0]}">${x[1]}</button>`).join('')}</div><div id="adminBody"></div>`;document.querySelectorAll('[data-admin]').forEach(x=>x.onclick=()=>admin(x.dataset.admin));renderAdmin(section);actions([{label:'Add Tool',primary:true,fn:()=>toolAdmin()},{label:'Tool Countdown',fn:()=>setView('countdown')}],false)}
function renderAdmin(s){let b=$('#adminBody');if(s==='home')b.innerHTML=`<div class="admin-launch-grid">${[['tools','Universal Tool Admin','Complete master tool record and both progress tracks.'],['countdown','Tool Countdown Admin','Quarter plan, pull-in/push-out and three-state shipping status.'],['shipping','Shipping Schedule Admin','Create/publish/update handoff schedules.'],['daily','Weekday Priorities Admin','Order and assign the normal full-crew weekday plan.'],['meeting','Morning Quick Update','Fast update of tool status before the manager meeting.'],['weekend','Weekend Plan Admin','Enter volunteers/hours first, then build weekend priorities.'],['config','Configuration','Rename fields, add/reorder Lead tasks, edit dropdowns and add custom Tool fields.']].map(x=>`<div class="admin-launch" data-open="${x[0]}"><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join('')}</div>`;if(s==='tools')b.innerHTML=`<div class="panel"><div class="subsection-title"><h3>Universal Tool Admin</h3><button id="newTool" class="btn primary">Add Tool</button></div><div class="table-wrap"><table class="report-table"><thead><tr><th>${esc(lbl('utid','UTID'))}</th><th>Code Name</th><th>Model</th><th>${esc(lbl('customer','Customer'))}</th><th>${esc(lbl('shipDate','MFG Ship'))}</th><th>Status</th><th></th></tr></thead><tbody>${tools.map(t=>`<tr><td><b>${esc(t.id)}</b></td><td>${esc(t.codename)}</td><td>${esc(t.model)}</td><td>${esc(t.customer)}</td><td>${fmt(t.ship)}</td><td>${esc(t.quarterStatus)}</td><td><button class="btn small" data-edit="${esc(t.id)}">Edit</button></td></tr>`).join('')}</tbody></table></div></div>`;if(s==='countdown')b.innerHTML=countdownAdmin();if(s==='shipping')b.innerHTML=shippingAdmin();if(s==='daily')b.innerHTML=priorityAdmin('daily');if(s==='meeting')b.innerHTML=morningAdmin();if(s==='weekend')b.innerHTML=weekendAdmin();if(s==='config')b.innerHTML=configPage();document.querySelectorAll('[data-open]').forEach(x=>x.onclick=()=>admin(x.dataset.open));document.querySelectorAll('[data-edit]').forEach(x=>x.onclick=()=>toolAdmin(x.dataset.edit));if($('#newTool'))$('#newTool').onclick=()=>toolAdmin();wireAdmin(s)}
function listInput(value,list,id,cls=''){return `<input ${id?`id="${id}"`:''} class="${cls}" list="${list}" value="${esc(value)}">`}
function datalist(id,values){return `<datalist id="${id}">${[...new Set(values.filter(Boolean))].map(x=>`<option value="${esc(x)}"></option>`).join('')}</datalist>`}
function remembered(key){return tools.map(t=>t[key]).filter(Boolean)}
function codenameOptions(v){return Object.keys(PRODUCT_CATALOG).map(x=>`<option value="${x}" ${x===v?'selected':''}>${x}</option>`).join('')}
function modelOptions(code,v){let a=[...(PRODUCT_CATALOG[code]||[])];if(v&&!a.includes(v))a.push(v);return a.map(x=>`<option value="${esc(x)}" ${x===v?'selected':''}>${esc(x)}</option>`).join('')}
function quarterOptions(v){let a=[...QUARTERS];if(v&&!a.includes(v))a.push(v);return a.map(x=>`<option value="${x}" ${x===v?'selected':''}>${x}</option>`).join('')}
function countdownAdmin(){return `<div class="panel"><h3>Quarter Tool Shipping Countdown Admin</h3><p class="helper">Workbook fields are included. Product Model is limited by Code Name. Other text values can be entered manually.</p><div class="table-wrap"><table class="report-table compact-form-table"><thead><tr><th>Quarter</th><th>Family</th><th>Code Name</th><th>Model</th><th>Customer</th><th>Sales Order</th><th>UTID</th><th>MFG Ship</th><th>Pull-In</th><th>Push-Out</th><th>Next Quarter Tool</th><th>Pulled In From</th><th>Status</th></tr></thead><tbody>${tools.map(t=>`<tr data-cd="${esc(t.id)}"><td><select class="cd-quarter">${quarterOptions(t.quarter)}</select></td><td>29XX</td><td><select class="cd-code">${codenameOptions(t.codename)}</select></td><td><select class="cd-model">${modelOptions(t.codename,t.model)}</select></td><td><input class="cd-customer" list="customers" value="${esc(t.customer)}"></td><td><input class="cd-so" value="${esc(t.so)}"></td><td><input class="cd-id" value="${esc(t.id)}"></td><td><input class="cd-ship" type="date" value="${esc(t.ship)}"></td><td><input class="cd-pull" type="date" value="${esc(t.pullIn)}"></td><td><input class="cd-push" type="date" value="${esc(t.pushOut)}"></td><td><input class="cd-next" list="quarters" value="${esc(t.nextQuarter)}"></td><td><input class="cd-from" list="quarters" value="${esc(t.pulledInFrom)}"></td><td><select class="cd-status"><option ${t.quarterStatus==='Waiting for FI'?'selected':''}>Waiting for FI</option><option ${t.quarterStatus==='In FI'?'selected':''}>In FI</option><option ${t.quarterStatus==='Shipped'?'selected':''}>Shipped</option></select></td></tr>`).join('')}</tbody></table></div>${datalist('customers',remembered('customer'))}${datalist('quarters',QUARTERS)}<div class="actions" style="margin-top:12px"><button id="saveCountdown" class="btn primary">Save Countdown Changes</button></div></div>`}
function shippingAdmin(){return `<div class="panel"><h3>Shipping Schedule Admin</h3><div class="table-wrap"><table class="report-table compact-form-table"><thead><tr><th>System</th><th>MFG Ship</th><th>Code Name</th><th>Cleanroom</th><th>Publish</th><th>Schedule Status</th><th>Subsystems</th><th>Cable Kit</th><th>Accessories</th><th>MST</th><th>IS</th><th>Notes</th></tr></thead><tbody>${tools.map(t=>`<tr data-sh="${esc(t.id)}"><td><b>${esc(t.id)}</b></td><td>${fmt(t.ship)}</td><td>${esc(t.codename)}</td><td>${esc(t.room)}</td><td><select class="sh-pub"><option>Draft</option><option ${t.schedule.publish==='Published'?'selected':''}>Published</option><option ${t.schedule.publish==='Complete'?'selected':''}>Complete</option></select></td><td><select class="sh-stat"><option ${t.schedule.status==='In Progress'?'selected':''}>In Progress</option><option ${t.schedule.status==='Updated'?'selected':''}>Updated</option><option ${t.schedule.status==='Completed'?'selected':''}>Completed</option></select></td><td><input class="sh-sub" type="date" value="${esc(t.schedule.subsystems)}"></td><td><input class="sh-cab" type="date" value="${esc(t.schedule.cables)}"></td><td><input class="sh-acc" type="date" value="${esc(t.schedule.accessories)}"></td><td><input class="sh-mst" placeholder="Date or N/A" value="${esc(t.schedule.mst)}"></td><td><input class="sh-is" type="date" value="${esc(t.schedule.is)}"></td><td><input class="sh-note" value="${esc(t.schedule.notes)}"></td></tr>`).join('')}</tbody></table></div><div class="actions" style="margin-top:12px"><button id="saveShipping" class="btn primary">Save Shipping Schedules</button></div></div>`}
function priorityOptions(v){return `<option value="">None</option>`+Array.from({length:50},(_,i)=>i+1).map(n=>`<option value="${n}" ${n===v?'selected':''}>${n}</option>`).join('')}
function routeOptions(t){let a=routeFor(t);return a.map(x=>`<option value="${x[0]}" ${x[0]===t.checklist?'selected':''}>${x[0]} — ${x[1]}</option>`).join('')}
function priorityAdmin(type){let key=type==='weekend'?'weekendPriority':'dailyPriority',ass=type==='weekend'?'weekendAssignment':'weekdayAssignment',notes=type==='weekend'?'weekendNotes':'priorityNotes';return `<div class="panel"><div class="form-group" style="max-width:600px"><label>Report Title</label><input id="priorityTitle" value="${esc(type==='weekend'?state.weekend.title:state.weekday.title)}"></div><div class="table-wrap"><table class="report-table compact-form-table"><thead><tr><th>UTID</th><th>Priority</th><th>Model</th><th>Sales Order</th><th>Customer</th><th>Ship Date</th><th>Cleanroom</th><th>Tool Assignment</th><th>Notes</th></tr></thead><tbody>${tools.filter(t=>t.quarterStatus!=='Shipped').map(t=>`<tr data-pr="${esc(t.id)}"><td><b>${esc(t.id)}</b></td><td><select class="pr-num">${priorityOptions(t[key])}</select></td><td>${esc(t.model)}</td><td>${esc(t.so)}</td><td>${esc(t.customer)}</td><td>${fmt(t.ship)}</td><td><input class="pr-room" list="rooms" value="${esc(t.room)}"></td><td><input class="pr-ass" list="people" value="${esc(t[ass]||t.driver)}"></td><td><input class="pr-note" value="${esc(t[notes]||'')}"></td></tr>`).join('')}</tbody></table></div>${datalist('rooms',['CR1','CR2','CR3',...remembered('room')])}${datalist('people',[...remembered('driver'),...remembered('weekdayAssignment'),...remembered('weekendAssignment'),...(state.weekend.volunteers||[]).map(x=>x.name)])}<div class="actions" style="margin-top:12px"><button id="savePriority" data-type="${type}" class="btn primary">Save ${type==='weekend'?'Weekend':'Weekday'} Priorities</button></div></div>`}
function volunteerAdmin(){let v=state.weekend.volunteers||[];return `<div class="panel"><div class="subsection-title"><h3>Weekend Volunteers / Hours</h3><button id="addVolunteer" class="btn">+ Add Volunteer</button></div><div class="table-wrap"><table class="report-table"><thead><tr><th>Name</th><th>Saturday Hours</th><th>Sunday Hours</th><th>Notes</th><th></th></tr></thead><tbody id="volRows">${v.map((x,i)=>volRow(x,i)).join('')}</tbody></table></div></div>`}
function volRow(x,i){return `<tr data-vol="${i}"><td><input class="vol-name" list="peopleMemory" value="${esc(x.name)}"></td><td><input class="vol-sat" value="${esc(x.sat)}"></td><td><input class="vol-sun" value="${esc(x.sun)}"></td><td><input class="vol-note" value="${esc(x.notes)}"></td><td><button class="btn danger small vol-remove">Remove</button></td></tr>`}
function weekendAdmin(){return `${volunteerAdmin()}${datalist('peopleMemory',[...remembered('driver'),...remembered('weekdayAssignment'),...remembered('weekendAssignment'),...(state.weekend.volunteers||[]).map(x=>x.name)])}${priorityAdmin('weekend')}`}
function morningAdmin(){return `<div class="panel"><h3>Morning Quick Update</h3><p class="helper">These edits update the Tool record itself, so the Morning Status and other pages stay synchronized.</p><div class="table-wrap"><table class="report-table compact-form-table"><thead><tr><th>UTID</th><th>Cleanroom</th><th>SW Version</th><th>Current Checklist</th><th>Lamp Hours</th><th>FI Status</th><th>Latest Status</th></tr></thead><tbody>${tools.filter(t=>t.quarterStatus!=='Shipped').map(t=>`<tr data-m="${esc(t.id)}"><td><b>${esc(t.id)}</b></td><td><input class="m-room" list="roomsMorning" value="${esc(t.room)}"></td><td><input class="m-sw" list="swMemory" value="${esc(t.sw)}"></td><td><select class="m-check">${routeOptions(t)}</select></td><td><input class="m-lamp" type="number" value="${t.lamp||0}"></td><td><select class="m-status"><option ${t.fiStatus==='Progressing'?'selected':''}>Progressing</option><option ${t.fiStatus==='Performing POA'?'selected':''}>Performing POA</option><option ${t.fiStatus==='Line Down'?'selected':''}>Line Down</option></select></td><td><input class="m-act" list="activityMemory" value="${esc(t.activity)}"></td></tr>`).join('')}</tbody></table></div>${datalist('roomsMorning',['CR1','CR2','CR3',...remembered('room')])}${datalist('swMemory',remembered('sw'))}${datalist('activityMemory',remembered('activity'))}<div class="actions" style="margin-top:12px"><button id="saveMorning" class="btn primary">Save Morning Updates</button></div></div>`}
function configPage(){let c=state.config;return `<div class="config-note"><b>Future-proof configuration:</b> Lead/Admin tasks and custom Tool fields use stable internal IDs. Renaming a field changes its display name without deleting saved tool values. Core system fields are protected, but their display labels can be renamed.</div><section class="config-section panel"><h3>Core Tool Field Display Names</h3><p class="gray">Rename labels only. The underlying universal field stays the same everywhere.</p><div class="table-wrap"><table class="report-table config-table"><thead><tr><th>System Field</th><th>Display Name</th><th>Protection</th></tr></thead><tbody>${CORE_FIELD_DEFS.map(([id,def])=>`<tr data-core="${id}"><td><code>${id}</code></td><td><input class="core-label wide-input" value="${esc(c.labels[id]||def)}"></td><td><span class="protected">Protected data field</span></td></tr>`).join('')}</tbody></table></div></section><section class="config-section panel"><div class="subsection-title"><div><h3>Lead / Admin Workflow Builder</h3><p class="gray">This order becomes the Lead/Admin sequence shown on every Tool page and drives the Lead/Admin progress bar.</p></div><button id="addLeadTask" class="btn">+ Add Task</button></div><div class="table-wrap"><table class="report-table config-table"><thead><tr><th>#</th><th>Task / Field Name</th><th>Dropdown Choices</th><th>Progress?</th><th>Active?</th><th>Actions</th></tr></thead><tbody id="leadConfigRows">${c.leadTasks.map((t,i)=>leadConfigRow(t,i)).join('')}</tbody></table></div></section><section class="config-section panel"><div class="subsection-title"><div><h3>Custom Tool Fields</h3><p class="gray">Add extra universal fields without changing code. Values are stored once per Tool and shown everywhere that uses the field.</p></div><button id="addCustomField" class="btn">+ Add Field</button></div><div class="table-wrap"><table class="report-table config-table"><thead><tr><th>#</th><th>Field Name</th><th>Section</th><th>Type</th><th>Dropdown Choices</th><th>Manual Entry?</th><th>Show on Tool Status?</th><th>Active?</th><th>Actions</th></tr></thead><tbody id="customConfigRows">${c.customFields.map((f,i)=>customConfigRow(f,i)).join('')}</tbody></table></div></section><div class="actions"><button id="saveConfig" class="btn primary">Save Configuration</button></div>`}
function leadConfigRow(t,i){return `<tr data-lead-id="${esc(t.id)}"><td><span class="order-pill">${i+1}</span></td><td><input class="lead-label wide-input" value="${esc(t.label)}"></td><td><input class="lead-options choices-input" value="${esc((t.options||DEFAULT_TASK_CHOICES).join(' | '))}"></td><td><input class="lead-progress" type="checkbox" ${t.countProgress!==false?'checked':''}></td><td><input class="lead-active" type="checkbox" ${t.active!==false?'checked':''}></td><td><div class="config-actions"><button class="btn small cfg-up" data-kind="lead" data-i="${i}">↑</button><button class="btn small cfg-down" data-kind="lead" data-i="${i}">↓</button><button class="btn danger small cfg-del" data-kind="lead" data-i="${i}">Delete</button></div></td></tr>`}
function customConfigRow(f,i){return `<tr data-custom-id="${esc(f.id)}"><td><span class="order-pill">${i+1}</span></td><td><input class="cf-label wide-input" value="${esc(f.label)}"></td><td><select class="cf-section"><option ${f.section==='Tool Information'?'selected':''}>Tool Information</option><option ${f.section==='Tool Progress'?'selected':''}>Tool Progress</option><option ${f.section==='Lead / Admin'?'selected':''}>Lead / Admin</option><option ${f.section==='Shipping'?'selected':''}>Shipping</option><option ${f.section==='Other'?'selected':''}>Other</option></select></td><td><select class="cf-type"><option ${f.type==='Text'?'selected':''}>Text</option><option ${f.type==='Number'?'selected':''}>Number</option><option ${f.type==='Date'?'selected':''}>Date</option><option ${f.type==='Dropdown'?'selected':''}>Dropdown</option></select></td><td><input class="cf-options choices-input" value="${esc((f.options||[]).join(' | '))}"></td><td><input class="cf-manual" type="checkbox" ${f.allowCustom!==false?'checked':''}></td><td><input class="cf-status" type="checkbox" ${f.showStatus!==false?'checked':''}></td><td><input class="cf-active" type="checkbox" ${f.active!==false?'checked':''}></td><td><div class="config-actions"><button class="btn small cfg-up" data-kind="custom" data-i="${i}">↑</button><button class="btn small cfg-down" data-kind="custom" data-i="${i}">↓</button><button class="btn danger small cfg-del" data-kind="custom" data-i="${i}">Delete</button></div></td></tr>`}
function collectConfigFromDom(){document.querySelectorAll('[data-core]').forEach(r=>state.config.labels[r.dataset.core]=r.querySelector('.core-label').value.trim()||r.dataset.core);let lead=[];document.querySelectorAll('[data-lead-id]').forEach(r=>lead.push({id:r.dataset.leadId,label:r.querySelector('.lead-label').value.trim()||'Untitled Task',options:r.querySelector('.lead-options').value.split('|').map(x=>x.trim()).filter(Boolean),countProgress:r.querySelector('.lead-progress').checked,active:r.querySelector('.lead-active').checked}));state.config.leadTasks=lead;let custom=[];document.querySelectorAll('[data-custom-id]').forEach(r=>custom.push({id:r.dataset.customId,label:r.querySelector('.cf-label').value.trim()||'Untitled Field',section:r.querySelector('.cf-section').value,type:r.querySelector('.cf-type').value,options:r.querySelector('.cf-options').value.split('|').map(x=>x.trim()).filter(Boolean),allowCustom:r.querySelector('.cf-manual').checked,showStatus:r.querySelector('.cf-status').checked,active:r.querySelector('.cf-active').checked}));state.config.customFields=custom;tools.forEach(t=>syncToolConfig(t,state.config))}
function moveConfig(kind,i,delta){collectConfigFromDom();let a=kind==='lead'?state.config.leadTasks:state.config.customFields,j=i+delta;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];renderAdmin('config')}
function deleteConfig(kind,i){collectConfigFromDom();let a=kind==='lead'?state.config.leadTasks:state.config.customFields,item=a[i];if(!item)return;if(!confirm(`Deactivate/delete ${item.label}? Existing saved values will be preserved internally where possible.`))return;a.splice(i,1);renderAdmin('config')}
function wireConfig(){if($('#addLeadTask'))$('#addLeadTask').onclick=()=>{collectConfigFromDom();let id='lead_custom_'+state.config.nextLeadId++;state.config.leadTasks.push({id,label:'New Lead / Admin Task',options:[...DEFAULT_TASK_CHOICES],active:true,countProgress:true});tools.forEach(t=>t.leadAdmin[id]='Not Started');renderAdmin('config')};if($('#addCustomField'))$('#addCustomField').onclick=()=>{collectConfigFromDom();let id='custom_'+state.config.nextCustomId++;state.config.customFields.push({id,label:'New Tool Field',section:'Other',type:'Dropdown',options:['Not Started','Complete','N/A'],allowCustom:true,showStatus:true,active:true});tools.forEach(t=>t.custom[id]='');renderAdmin('config')};document.querySelectorAll('.cfg-up').forEach(b=>b.onclick=()=>moveConfig(b.dataset.kind,Number(b.dataset.i),-1));document.querySelectorAll('.cfg-down').forEach(b=>b.onclick=()=>moveConfig(b.dataset.kind,Number(b.dataset.i),1));document.querySelectorAll('.cfg-del').forEach(b=>b.onclick=()=>deleteConfig(b.dataset.kind,Number(b.dataset.i)));if($('#saveConfig'))$('#saveConfig').onclick=()=>{collectConfigFromDom();save();alert('Configuration saved. Tool pages now use the updated field names, task order, and dropdown choices.');admin('config')}}
function wireAdmin(s){if(s==='config'){wireConfig();return}if($('#saveCountdown'))$('#saveCountdown').onclick=()=>{document.querySelectorAll('[data-cd]').forEach(r=>{let t=tools.find(x=>x.id===r.dataset.cd),old=t.id;t.quarter=r.querySelector('.cd-quarter').value;t.codename=r.querySelector('.cd-code').value;t.model=r.querySelector('.cd-model').value;t.customer=r.querySelector('.cd-customer').value;t.so=r.querySelector('.cd-so').value;t.id=r.querySelector('.cd-id').value.trim();t.ship=r.querySelector('.cd-ship').value;t.pullIn=r.querySelector('.cd-pull').value;t.pushOut=r.querySelector('.cd-push').value;t.nextQuarter=r.querySelector('.cd-next').value;t.pulledInFrom=r.querySelector('.cd-from').value;t.quarterStatus=r.querySelector('.cd-status').value});save();setView('countdown')};document.querySelectorAll('.cd-code').forEach(sel=>sel.onchange=()=>{let r=sel.closest('tr');r.querySelector('.cd-model').innerHTML=modelOptions(sel.value,'')});if($('#saveShipping'))$('#saveShipping').onclick=()=>{document.querySelectorAll('[data-sh]').forEach(r=>{let t=tools.find(x=>x.id===r.dataset.sh);t.schedule.publish=r.querySelector('.sh-pub').value;t.schedule.status=r.querySelector('.sh-stat').value;t.schedule.subsystems=r.querySelector('.sh-sub').value;t.schedule.cables=r.querySelector('.sh-cab').value;t.schedule.accessories=r.querySelector('.sh-acc').value;t.schedule.mst=r.querySelector('.sh-mst').value;t.schedule.is=r.querySelector('.sh-is').value;t.schedule.notes=r.querySelector('.sh-note').value;if(t.schedule.publish==='Complete')t.quarterStatus='Shipped'});save();setView('shipping')};if($('#savePriority'))$('#savePriority').onclick=()=>{let type=$('#savePriority').dataset.type,key=type==='weekend'?'weekendPriority':'dailyPriority',ass=type==='weekend'?'weekendAssignment':'weekdayAssignment',notes=type==='weekend'?'weekendNotes':'priorityNotes',rows=[...document.querySelectorAll('[data-pr]')],nums=rows.map(r=>r.querySelector('.pr-num').value).filter(Boolean);if(new Set(nums).size!==nums.length)return alert('Each priority number can only be used once on this list.');rows.forEach(r=>{let t=tools.find(x=>x.id===r.dataset.pr);t[key]=r.querySelector('.pr-num').value?Number(r.querySelector('.pr-num').value):null;t.room=r.querySelector('.pr-room').value;t[ass]=r.querySelector('.pr-ass').value;t[notes]=r.querySelector('.pr-note').value});if(type==='weekend')state.weekend.title=$('#priorityTitle').value;else state.weekday.title=$('#priorityTitle').value;if(type==='weekend'){state.weekend.volunteers=[...document.querySelectorAll('[data-vol]')].map(r=>({name:r.querySelector('.vol-name').value,sat:r.querySelector('.vol-sat').value,sun:r.querySelector('.vol-sun').value,notes:r.querySelector('.vol-note').value})).filter(x=>x.name)}save();setView(type==='weekend'?'weekend':'daily')};if($('#addVolunteer')){$('#addVolunteer').onclick=()=>{$('#volRows').insertAdjacentHTML('beforeend',volRow({name:'',sat:'',sun:'',notes:''},Date.now()));wireVolRemove()};wireVolRemove()}if($('#saveMorning'))$('#saveMorning').onclick=()=>{document.querySelectorAll('[data-m]').forEach(r=>{let t=tools.find(x=>x.id===r.dataset.m);t.room=r.querySelector('.m-room').value;t.sw=r.querySelector('.m-sw').value;t.checklist=r.querySelector('.m-check').value;t.lamp=Number(r.querySelector('.m-lamp').value)||0;t.fiStatus=r.querySelector('.m-status').value;t.activity=r.querySelector('.m-act').value});save();setView('meeting')}}
function wireVolRemove(){document.querySelectorAll('.vol-remove').forEach(b=>b.onclick=()=>b.closest('tr').remove())}
function field(label,id,val,type='text',list=''){return `<div class="form-group"><label>${label}</label><input id="${id}" type="${type}" ${list?`list="${list}"`:''} value="${esc(val)}"></div>`}
function toolAdmin(id){let original=id?tools.find(x=>x.id===id):null,t=original?clone(original):defaultTool();document.body.dataset.theme='admin';app.innerHTML=page(original?`Update Tool ${esc(t.id)}`:'Add Tool','Complete master Tool record. Changes feed all generated reports.','TOOL ADMIN')+`<div class="admin-tabs"><button class="admin-tab active" data-tab="basic">Tool Information</button><button class="admin-tab" data-tab="fi">Tool Progress</button><button class="admin-tab" data-tab="lead">Lead / Admin</button><button class="admin-tab" data-tab="shipping">Shipping</button><button class="admin-tab" data-tab="issues">NCs</button><button class="admin-tab" data-tab="custom">Custom Fields</button></div><div id="taBody"></div>`;let tab='basic';function collect(){if($('#ta-id')){t.id=$('#ta-id').value.trim();t.codename=$('#ta-code').value;t.model=$('#ta-model').value;t.so=$('#ta-so').value;t.customer=$('#ta-customer').value;t.room=$('#ta-room').value;t.quarterStatus=$('#ta-qstatus').value;t.driver=$('#ta-driver').value;t.ship=$('#ta-ship').value;t.sw=$('#ta-sw').value;t.process=$('#ta-process').value;t.lamp=Number($('#ta-lamp').value)||0;t.notes=$('#ta-notes').value;t.activity=$('#ta-act').value}if($('#ta-check')){t.checklist=$('#ta-check').value;t.escalationMeeting=$('#ta-escalation').value;t.poa=$('#ta-poa').value;t.fiStatus=$('#ta-fistat').value;t.waivers=$('#ta-waivers').value}document.querySelectorAll('[data-task-id]').forEach(x=>t.leadAdmin[x.dataset.taskId]=x.value);document.querySelectorAll('[data-custom-id]').forEach(x=>t.custom[x.dataset.customId]=x.value);if($('#sch-pub')){t.schedule.publish=$('#sch-pub').value;t.schedule.status=$('#sch-stat').value;t.schedule.subsystems=$('#sch-sub').value;t.schedule.cables=$('#sch-cab').value;t.schedule.accessories=$('#sch-acc').value;t.schedule.mst=$('#sch-mst').value;t.schedule.is=$('#sch-is').value;t.schedule.notes=$('#sch-notes').value}if(document.querySelector('.nc-card'))t.ncs=[...document.querySelectorAll('.nc-card')].map(r=>({id:r.querySelector('.nid').value,desc:r.querySelector('.ndesc').value,state:r.querySelector('.nstate').value,days:Number(r.querySelector('.ndays').value)||0,blocking:r.querySelector('.nblock').checked})).filter(n=>n.id||n.desc)}function draw(){let b=$('#taBody');if(tab==='basic')b.innerHTML=`<div class="panel"><div class="form-grid"><div class="form-group"><label>Product Family</label><input value="29XX" disabled></div><div class="form-group"><label>Code Name</label><select id="ta-code">${codenameOptions(t.codename)}</select></div><div class="form-group"><label>Model</label><select id="ta-model">${modelOptions(t.codename,t.model)}</select></div>${field(lbl('utid','UTID'),'ta-id',t.id)}${field(lbl('salesOrder','Sales Order'),'ta-so',t.so)}${field(lbl('customer','Customer'),'ta-customer',t.customer,'text','customerMemory')}<div class="form-group"><label>${esc(lbl('cleanroom','Cleanroom'))}</label><input id="ta-room" list="roomMemory" value="${esc(t.room)}"></div><div class="form-group"><label>${esc(lbl('toolStatus','Tool Status'))}</label><select id="ta-qstatus"><option ${t.quarterStatus==='Waiting for FI'?'selected':''}>Waiting for FI</option><option ${t.quarterStatus==='In FI'?'selected':''}>In FI</option><option ${t.quarterStatus==='Shipped'?'selected':''}>Shipped</option></select></div>${field(lbl('assignment','Tool Assignment'),'ta-driver',t.driver,'text','peopleMemory')}${field(lbl('shipDate','MFG Ship Date'),'ta-ship',t.ship,'date')}${field(lbl('swVersion','SW Version'),'ta-sw',t.sw,'text','swMemory')}<div class="form-group"><label>${esc(lbl('fiProcess','FI Process'))}</label><select id="ta-process"><option ${t.process==='Full Process'?'selected':''}>Full Process</option><option ${t.process==='Reduced Process'?'selected':''}>Reduced Process</option></select></div>${field(lbl('lampHours','Lamp Hours'),'ta-lamp',t.lamp,'number')}<div class="form-group wide"><label>Notes</label><textarea id="ta-notes">${esc(t.notes)}</textarea></div><div class="form-group wide"><label>${esc(lbl('latestStatus','Latest Status'))}</label><textarea id="ta-act">${esc(t.activity)}</textarea></div></div>${datalist('customerMemory',remembered('customer'))}${datalist('roomMemory',['CR1','CR2','CR3',...remembered('room')])}${datalist('peopleMemory',[...remembered('driver'),...(state.weekend.volunteers||[]).map(x=>x.name)])}${datalist('swMemory',remembered('sw'))}</div>`;if(tab==='fi')b.innerHTML=`<div class="panel"><div class="metric-grid"><div class="metric"><span>Tool Progress</span><strong>${routeProgress(t)}%</strong><small>${esc(t.checklist)}</small></div></div><div class="form-grid"><div class="form-group"><label>${esc(lbl('currentChecklist','Current Checklist'))}</label><select id="ta-check">${routeOptions(t)}</select></div>${field('Open NCs / details are managed on NC tab','noop','See NC tab','text')}<div class="form-group"><label>Escalation Meeting</label><select id="ta-escalation"><option ${t.escalationMeeting==='N/A'?'selected':''}>N/A</option><option ${t.escalationMeeting==='Yes'?'selected':''}>Yes</option></select></div><div class="form-group"><label>POA</label><select id="ta-poa"><option ${t.poa==='N/A'?'selected':''}>N/A</option><option ${t.poa==='Completed latest POA'?'selected':''}>Completed latest POA</option><option ${t.poa==='Performing latest POA'?'selected':''}>Performing latest POA</option></select></div><div class="form-group"><label>Status</label><select id="ta-fistat"><option ${t.fiStatus==='Progressing'?'selected':''}>Progressing</option><option ${t.fiStatus==='Performing POA'?'selected':''}>Performing POA</option><option ${t.fiStatus==='Line Down'?'selected':''}>Line Down</option></select></div><div class="form-group wide"><label>Waivers</label><textarea id="ta-waivers">${esc(t.waivers)}</textarea></div></div><h3 style="margin-top:18px">Ordered FI Checklist Route</h3>${routeWorkflow(t)}</div>`;if(tab==='lead')b.innerHTML=`<div class="panel"><div class="metric-grid"><div class="metric"><span>Lead / Admin Progress</span><strong>${adminProgress(t)}%</strong><small>Ordered workflow from Configuration</small></div></div>${leadWorkflow(t,true)}</div>`;if(tab==='custom'){let fs=(state.config.customFields||[]).filter(f=>f.active!==false);b.innerHTML=`<div class="panel"><h3>Configurable Tool Fields</h3><p class="gray">These fields were added from Administration → Configuration. Values are universal for this Tool.</p><div class="custom-field-grid">${fs.map(f=>`<div class="form-group"><label>${esc(f.label)}</label>${customFieldValueControl(f,t)}<div class="field-preview">${esc(f.section)} · ${esc(f.type)}${f.allowCustom?' · manual entry allowed':''}</div></div>`).join('')||'<p class="gray">No custom fields have been configured.</p>'}</div></div>`;}if(tab==='shipping')b.innerHTML=`<div class="panel"><div class="form-grid"><div class="form-group"><label>Publish Status</label><select id="sch-pub"><option ${t.schedule.publish==='Draft'?'selected':''}>Draft</option><option ${t.schedule.publish==='Published'?'selected':''}>Published</option><option ${t.schedule.publish==='Complete'?'selected':''}>Complete</option></select></div><div class="form-group"><label>Ship Schedule</label><select id="sch-stat"><option ${t.schedule.status==='In Progress'?'selected':''}>In Progress</option><option ${t.schedule.status==='Updated'?'selected':''}>Updated</option><option ${t.schedule.status==='Completed'?'selected':''}>Completed</option></select></div>${field('Subsystems Handoff','sch-sub',t.schedule.subsystems,'date')}${field('Cable Kit Handoff','sch-cab',t.schedule.cables,'date')}${field('Accessories Handoff','sch-acc',t.schedule.accessories,'date')}${field('MST Install (date or N/A)','sch-mst',t.schedule.mst)}${field('IS Handoff','sch-is',t.schedule.is,'date')}<div class="form-group wide"><label>Notes</label><textarea id="sch-notes">${esc(t.schedule.notes)}</textarea></div></div></div>`;if(tab==='issues')b.innerHTML=`<div class="panel"><div class="subsection-title"><h3>Open / Escalated NCs</h3><button id="addNc" class="btn">+ Add NC</button></div><div id="ncList">${t.ncs.map((n,i)=>ncRow(n,i)).join('')||'<p class="gray">No critical NCs tracked.</p>'}</div></div>`;if($('#ta-code'))$('#ta-code').onchange=()=>{$('#ta-model').innerHTML=modelOptions($('#ta-code').value,'')};if($('#addNc'))$('#addNc').onclick=()=>{collect();t.ncs.push({id:'',desc:'',state:'Open',days:0,blocking:false});draw()};document.querySelectorAll('.nc-remove').forEach(x=>x.onclick=()=>{collect();t.ncs.splice(Number(x.dataset.i),1);draw()})}function ncRow(n,i){return `<div class="nc-card"><div class="form-grid">${field2('NC #','nid',n.id)}${field2('Description','ndesc',n.desc)}<div class="form-group"><label>Status</label><select class="nstate"><option ${n.state==='Open'?'selected':''}>Open</option><option ${n.state==='Troubleshooting'?'selected':''}>Troubleshooting</option><option ${n.state==='Escalated'?'selected':''}>Escalated</option><option ${n.state==='POA In Progress'?'selected':''}>POA In Progress</option><option ${n.state==='Waiver Pending'?'selected':''}>Waiver Pending</option><option ${n.state==='Closed'?'selected':''}>Closed</option><option ${n.state==='Waived'?'selected':''}>Waived</option></select></div>${field2('Escalation Days','ndays',n.days,'number')}</div><label><input class="nblock" type="checkbox" ${n.blocking?'checked':''}> Blocking FI progression</label> <button class="btn danger small nc-remove" data-i="${i}">Remove</button></div>`}document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{collect();tab=x.dataset.tab;document.querySelectorAll('[data-tab]').forEach(y=>y.classList.toggle('active',y===x));draw()});draw();actions([{label:'Save Tool',primary:true,fn:()=>{collect();if(!t.id)return alert('UTID is required.');if(!original&&tools.some(x=>x.id===t.id))return alert('That UTID already exists.');if(original)tools[tools.findIndex(x=>x.id===original.id)]=normalize(t);else tools.push(normalize(t));save();toolStatus(t.id)}},{label:'Delete Tool',fn:()=>{if(original&&confirm('Delete this tool record?')){tools=tools.filter(x=>x.id!==original.id);save();setView('systems')}}},{label:'Administration',fn:()=>admin('tools')}],false)}
function field2(label,cls,val,type='text'){return `<div class="form-group"><label>${label}</label><input class="${cls}" type="${type}" value="${esc(val)}"></div>`}
function render(){if(view==='countdown')countdown();else if(view==='shipping')shipping();else if(view==='daily')daily();else if(view==='meeting')morning();else if(view==='weekend')weekend();else if(view==='systems')systems();else admin()}
render();app.dataset.rendered='true';
